INSERT INTO `improvement_plans` (`plan_id`, `school_id`, `cycle_id`, `dimension_id`, `indicator_id`, `priority_level`, `objective`, `strategy`, `person_responsible`, `target_date`, `resources_needed`, `expected_output`, `status`, `workflow_status`, `current_owner_role`, `current_owner_user_id`, `last_action_by`, `last_action_at`, `remarks`, `created_by`, `submitted_by`, `submitted_at`, `approved_by`, `approved_at`, `validated_by`, `validated_at`, `created_at`, `updated_at`, `suggestion_item_id`, `suggestion_baseline_text`) VALUES
(66, 1, 39, 6, 41, 'Medium', 'Achieve a 75‑100% utilization rate of the school’s Maintenance and Other Operating Expenses and ensure 100% liquidation of all utilized MOOE by the end of the fiscal year through a dedicated finance sub‑team, monthly MOOE dashboard monitoring, and the implementation of prioritized quick‑win projects.', 'The school will establish a finance sub‑team comprising the principal, finance officer, and a teacher to monitor monthly MOOE disbursements and expenditures and to maintain a MOOE Dashboard that displays utilization rates and pending items before each school board meeting, and will direct the available funds toward prioritized quick‑win projects such as classroom repairs and ICT tools so that 75 %–100 % of the MOOE is utilized and all utilized amounts are fully liquidated within the current budget cycle.', 'Planning together with school head and sbm coordinator', '2001-12-20', NULL, 'execute it by the end of the year', 'planned', 'finalized', NULL, NULL, 46, '2026-10-01 03:29:34', NULL, 37, 37, '2026-10-01 03:11:49', 46, '2026-10-01 03:29:25', 46, '2026-10-01 03:29:34', '2026-09-30 19:09:09', '2026-09-30 19:29:34', NULL, NULL),
(67, 1, 39, 6, 42, 'Medium', 'Achieve a 75‑100% utilization rate of the school’s Maintenance and Other Operating Expenses and ensure 100% liquidation of all utilized MOOE by the end of the fiscal year through a dedicated finance sub‑team, monthly MOOE dashboard monitoring, and the implementation of prioritized quick‑win projects.', 'The school will establish a finance sub‑team comprising the principal, finance officer, and a teacher to monitor monthly MOOE disbursements and expenditures and to maintain a MOOE Dashboard that displays utilization rates and pending items before each school board meeting, and will direct the available funds toward prioritized quick‑win projects such as classroom repairs and ICT tools so that 75 %–100 % of the MOOE is utilized and all utilized amounts are fully liquidated within the current budget cycle.', 'Planning together with school head and sbm coordinator', '2001-12-20', NULL, 'execute it by the end of the year', 'planned', 'submitted', 'sbm_coordinator', NULL, 37, '2026-10-01 03:11:49', NULL, 37, 37, '2026-10-01 03:11:49', NULL, NULL, NULL, NULL, '2026-09-30 19:09:09', '2026-09-30 19:11:49', NULL, NULL);
